package com.nigson.acceptance.inventory;
import com.nigson.commerce.inventory.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.security.ActorAssertion;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class InventoryPersistenceTest {
 InventoryFixture f;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"inventory-check supplies isolated owned PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");var jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);var metrics=new SimpleMeterRegistry();var clock=Clock.systemUTC();var commands=new PlatformStore(jdbc,manager,clock,metrics);var audit=new AuditWriter(jdbc,clock,metrics);var service=new InventoryService(new JdbcInventoryRepository(jdbc,clock),new InventoryAuthority(jdbc),commands,audit,clock,manager,jdbc,metrics);f=new InventoryFixture(jdbc,service,new JdbcStockLedger(jdbc,service,audit,clock),manager);}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 @Test void zeroLocationAndScaledAdjustmentsAreReplayableVersionedAndAtomic(){UUID location=f.location(),sku=f.sku(2);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_balance WHERE location_id=?",Integer.class,location)).isZero();String key=UUID.randomUUID().toString();var first=f.adjust(sku,location,"10.25",0,key);assertThat(first.onHand()).isEqualTo("10.25");assertThat(first.version()).isEqualTo(1);var next=f.adjust(sku,location,"-2.05",1,"next");assertThat(next.available()).isEqualTo("8.20");assertThat(f.adjust(sku,location,"10.25",0,key)).isEqualTo(first);UUID balance=f.balance(sku,location);assertThat(f.jdbc.queryForObject("SELECT sum(delta_on_hand)::text FROM commerce.inventory_movement WHERE balance_id=?",String.class,balance)).isEqualTo("8.200");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,balance)).isEqualTo(2);assertThat(EventCodec.decode(f.jdbc.queryForObject("SELECT payload::text FROM commerce.outbox_event WHERE aggregate_id=? ORDER BY aggregate_version DESC LIMIT 1",String.class,balance)).path("payload").path("available").asString()).isEqualTo("8.20");assertThatThrownBy(()->f.adjust(sku,location,"1.001",2,"scale")).hasMessage("VALIDATION_ERROR");assertThatThrownBy(()->f.adjust(sku,location,"1",0,"stale")).hasMessage("VERSION_MISMATCH");assertThatThrownBy(()->f.adjust(sku,location,"11",0,key)).hasMessage("IDEMPOTENCY_HASH_MISMATCH");}
 @Test void currentAuthorityIsCheckedBeforeCachedReplayAndInvalidInitialStockRollsBack(){UUID location=f.location(),sku=f.sku(0);assertThatThrownBy(()->f.adjust(sku,location,"-1",0,"negative")).hasMessage("INVENTORY_RULE_VIOLATION");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_balance WHERE sku_id=?",Integer.class,sku)).isZero();f.adjust(sku,location,"1",0,"positive");f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=?",f.operator);assertThatThrownBy(()->f.adjust(sku,location,"1",0,"positive")).hasMessage("ACCESS_DENIED");var fake=new ActorAssertion.Actor(f.operator,f.actor.identityIssuer(),"wrong",null,Set.of("OPERATIONS"),Set.of(),Instant.now());assertThatThrownBy(()->f.service.list(fake,new InventoryValues.Query(null,null,0,20,"skuId,asc"))).hasMessage("ACCESS_DENIED");}
 @Test void auditPermissionFailureRollsBackBalanceMovementOutboxAndSameCommandRecovers(){UUID location=f.location(),sku=f.sku(0);f.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->f.adjust(sku,location,"4",0,"audit")).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_balance WHERE sku_id=?",Integer.class,sku)).isZero();}finally{f.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(f.adjust(sku,location,"4",0,"audit").onHand()).isEqualTo("4");}
 @Test void twelveSameHeaderAdjustmentsProduceOneMovementAndAcknowledgement()throws Exception{UUID location=f.location(),sku=f.sku(0);String key=UUID.randomUUID().toString();var start=new CyclicBarrier(12);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var futures=new ArrayList<Future<InventoryValues.Stock>>();for(int i=0;i<12;i++)futures.add(pool.submit(()->{start.await();for(int n=0;n<30;n++)try{return f.adjust(sku,location,"1",0,key);}catch(PlatformStore.Conflict busy){if(!busy.getMessage().equals("IDEMPOTENCY_IN_PROGRESS"))throw busy;Thread.sleep(40);}throw new IllegalStateException("BOUNDED_REPLAY_EXHAUSTED");}));for(var result:futures)assertThat(result.get(10,TimeUnit.SECONDS).onHand()).isEqualTo("1");}assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_movement WHERE balance_id=?",Integer.class,f.balance(sku,location))).isEqualTo(1);}
 @Test void reservationProtectsCommittedStockAndCancellationReleaseIsExactlyOnce(){UUID location=f.location(),sku=f.sku(0);f.adjust(sku,location,"2",0,"stock");UUID balance=f.balance(sku,location),order=f.orders.order(),reserve=UUID.randomUUID();f.line(order,sku,"2");var held=f.tx.<List<InventoryValues.Stock>>execute(s->f.ledger.reserve(order,Map.of(balance,"2"),Instant.now().plusSeconds(600),reserve,f.operator.toString(),UUID.randomUUID()));assertThat(held.getFirst().available()).isEqualTo("0");assertThatThrownBy(()->f.adjust(sku,location,"-1",2,"reduce-held")).hasMessage("INVENTORY_RULE_VIOLATION");assertThatThrownBy(()->f.tx.<List<InventoryValues.Stock>>execute(s->f.ledger.allocate(order,UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()))).hasMessage("INVENTORY_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.sales_order SET status='CANCELLED' WHERE id=?",order);UUID release=UUID.randomUUID();var freed=f.tx.<List<InventoryValues.Stock>>execute(s->f.ledger.release(order,release,f.operator.toString(),UUID.randomUUID()));assertThat(freed.getFirst().available()).isEqualTo("2");assertThat(f.tx.<List<InventoryValues.Stock>>execute(s->f.ledger.release(order,release,f.operator.toString(),UUID.randomUUID()))).isEqualTo(freed);}
 @Test void callerCheckoutTransactionRollsBackOrderAndAllLinesWhenAnyBalanceIsInsufficient(){UUID location=f.location(),one=f.sku(0),two=f.sku(0);f.adjust(one,location,"1",0,"one");f.adjust(two,location,"1",0,"two");f.adjust(two,location,"-1",1,"empty");UUID b1=f.balance(one,location),b2=f.balance(two,location);UUID[] order={null};assertThatThrownBy(()->f.tx.executeWithoutResult(s->{order[0]=f.orders.order();f.line(order[0],one,"1");f.line(order[0],two,"1");f.ledger.reserve(order[0],Map.of(b1,"1",b2,"1"),Instant.now().plusSeconds(600),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID());})).hasMessage("INVENTORY_RULE_VIOLATION");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.sales_order WHERE id=?",Integer.class,order[0])).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_reservation WHERE order_id=?",Integer.class,order[0])).isZero();assertThat(f.jdbc.queryForObject("SELECT sum(reserved)::text FROM commerce.inventory_balance WHERE id IN (?,?)",String.class,b1,b2)).isEqualTo("0.000");}
 @Test void twoOrdersRacingForLastUnitAdmitOneWithoutOverselling()throws Exception{UUID location=f.location(),sku=f.sku(0);f.adjust(sku,location,"1",0,"stock");UUID balance=f.balance(sku,location),one=f.orders.order(),two=f.orders.order();f.line(one,sku,"1");f.line(two,sku,"1");var start=new CyclicBarrier(2);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var results=new ArrayList<Future<Boolean>>();for(UUID order:List.of(one,two))results.add(pool.submit(()->{start.await();try{f.tx.executeWithoutResult(s->f.ledger.reserve(order,Map.of(balance,"1"),Instant.now().plusSeconds(600),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));return true;}catch(com.nigson.shared.problem.Problem.Failure denied){assertThat(denied.code.name()).isEqualTo("INVENTORY_RULE_VIOLATION");return false;}}));int admitted=0;for(var r:results)if(r.get(10,TimeUnit.SECONDS))admitted++;assertThat(admitted).isEqualTo(1);}assertThat(f.jdbc.queryForObject("SELECT reserved::text FROM commerce.inventory_balance WHERE id=?",String.class,balance)).isEqualTo("1.000");}
 @Test void verifiedAllocationPartialDispatchAndCappedExplicitReturnsReconcileExactly(){UUID location=f.location(),sku=f.sku(0);f.adjust(sku,location,"5",0,"stock");UUID balance=f.balance(sku,location),order=f.orders.order(),line=f.line(order,sku,"5");f.tx.executeWithoutResult(s->f.ledger.reserve(order,Map.of(balance,"5"),Instant.now().plusSeconds(600),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));f.paid(order);f.tx.executeWithoutResult(s->f.ledger.allocate(order,UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));UUID dispatch=UUID.randomUUID();var shipped=f.tx.<List<InventoryValues.Stock>>execute(s->f.ledger.dispatch(order,List.of(new StockLedger.Line(line,balance,"2")),dispatch,f.operator.toString(),UUID.randomUUID()));assertThat(shipped.getFirst().onHand()).isEqualTo("3");assertThat(shipped.getFirst().allocated()).isEqualTo("3");assertThat(f.tx.<List<InventoryValues.Stock>>execute(s->f.ledger.dispatch(order,List.of(new StockLedger.Line(line,balance,"2")),dispatch,f.operator.toString(),UUID.randomUUID()))).isEqualTo(shipped);UUID returned=UUID.randomUUID();f.tx.executeWithoutResult(s->f.ledger.returned(order,List.of(new StockLedger.Line(line,balance,"1")),StockLedger.ReturnKind.PHYSICAL_RETURN,"synthetic-receipt","Synthetic verified physical receipt",returned,f.operator.toString(),UUID.randomUUID()));assertThatThrownBy(()->f.tx.<List<InventoryValues.Stock>>execute(s->f.ledger.returned(order,List.of(new StockLedger.Line(line,balance,"2")),StockLedger.ReturnKind.PHYSICAL_RETURN,"other-receipt","Synthetic verified physical receipt",UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()))).hasMessage("INVENTORY_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.sales_order SET status='REFUNDING' WHERE id=?",order);assertThat(f.jdbc.queryForObject("SELECT allocated::text FROM commerce.inventory_balance WHERE id=?",String.class,balance)).isEqualTo("3.000");f.tx.executeWithoutResult(s->f.ledger.returned(order,List.of(new StockLedger.Line(line,balance,"3")),StockLedger.ReturnKind.UNSHIPPED_CANCEL,"synthetic-cancel","Synthetic approved unshipped cancellation",UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));assertThat(f.jdbc.queryForObject("SELECT on_hand::text||':'||reserved::text||':'||allocated::text FROM commerce.inventory_balance WHERE id=?",String.class,balance)).isEqualTo("4.000:0.000:0.000");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_balance b WHERE b.id=? AND (b.on_hand,b.reserved,b.allocated)=(SELECT sum(delta_on_hand),sum(delta_reserved),sum(delta_allocated) FROM commerce.inventory_movement WHERE balance_id=b.id)",Integer.class,balance)).isEqualTo(1);}
 @Test void portCannotCreateItsOwnTransaction(){assertThatThrownBy(()->f.ledger.release(UUID.randomUUID(),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID())).hasMessage("LOCAL_TRANSACTION_REQUIRED");}
 @Test void oppositeInputOrdersUseTheSameGlobalBalanceLockOrder()throws Exception{UUID location=f.location(),one=f.sku(0),two=f.sku(0);f.adjust(one,location,"2",0,"one");f.adjust(two,location,"2",0,"two");UUID b1=f.balance(one,location),b2=f.balance(two,location),o1=f.orders.order(),o2=f.orders.order();for(UUID order:List.of(o1,o2)){f.line(order,one,"1");f.line(order,two,"1");}var first=new LinkedHashMap<UUID,String>();first.put(b1,"1");first.put(b2,"1");var reverse=new LinkedHashMap<UUID,String>();reverse.put(b2,"1");reverse.put(b1,"1");var start=new CyclicBarrier(2);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(()->{start.await();return f.tx.<List<InventoryValues.Stock>>execute(t->f.ledger.reserve(o1,first,Instant.now().plusSeconds(600),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));});var b=pool.submit(()->{start.await();return f.tx.<List<InventoryValues.Stock>>execute(t->f.ledger.reserve(o2,reverse,Instant.now().plusSeconds(600),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));});assertThat(a.get(10,TimeUnit.SECONDS)).hasSize(2);assertThat(b.get(10,TimeUnit.SECONDS)).hasSize(2);}assertThat(f.jdbc.queryForObject("SELECT sum(reserved)::text FROM commerce.inventory_balance WHERE id IN (?,?)",String.class,b1,b2)).isEqualTo("4.000");}
 @Test void uncertainSettlementOrHoldCannotAllocateAndReturnCommandCannotChangeKind(){UUID location=f.location(),sku=f.sku(0);f.adjust(sku,location,"2",0,"stock");UUID balance=f.balance(sku,location),order=f.orders.order(),line=f.line(order,sku,"2");Instant expiry=Instant.now().plusSeconds(600);UUID reserve=UUID.randomUUID();var held=f.tx.<List<InventoryValues.Stock>>execute(t->f.ledger.reserve(order,Map.of(balance,"2"),expiry,reserve,f.operator.toString(),UUID.randomUUID()));assertThat(f.tx.<List<InventoryValues.Stock>>execute(t->f.ledger.reserve(order,Map.of(balance,"2"),expiry,reserve,f.operator.toString(),UUID.randomUUID()))).isEqualTo(held);f.paid(order);f.jdbc.update("UPDATE commerce.payment_attempt SET state='UNKNOWN' WHERE order_id=?",order);assertThatThrownBy(()->f.tx.executeWithoutResult(t->f.ledger.allocate(order,UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()))).hasMessage("INVENTORY_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.payment_attempt SET state='SUCCEEDED' WHERE order_id=?",order);f.jdbc.update("UPDATE commerce.sales_order SET status='PAYMENT_HOLD',hold_reason='STOCK_UNAVAILABLE' WHERE id=?",order);assertThatThrownBy(()->f.tx.executeWithoutResult(t->f.ledger.allocate(order,UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()))).hasMessage("INVENTORY_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.sales_order SET status='PAID',hold_reason=NULL WHERE id=?",order);f.tx.executeWithoutResult(t->f.ledger.allocate(order,UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));f.tx.executeWithoutResult(t->f.ledger.dispatch(order,List.of(new StockLedger.Line(line,balance,"2")),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));UUID returned=UUID.randomUUID();var result=f.tx.<List<InventoryValues.Stock>>execute(t->f.ledger.returned(order,List.of(new StockLedger.Line(line,balance,"1")),StockLedger.ReturnKind.PHYSICAL_RETURN,"synthetic-receipt","Synthetic verified physical receipt",returned,f.operator.toString(),UUID.randomUUID()));assertThat(f.tx.<List<InventoryValues.Stock>>execute(t->f.ledger.returned(order,List.of(new StockLedger.Line(line,balance,"1")),StockLedger.ReturnKind.PHYSICAL_RETURN,"synthetic-receipt","Synthetic verified physical receipt",returned,f.operator.toString(),UUID.randomUUID()))).isEqualTo(result);assertThatThrownBy(()->f.tx.executeWithoutResult(t->f.ledger.returned(order,List.of(new StockLedger.Line(line,balance,"1")),StockLedger.ReturnKind.UNSHIPPED_CANCEL,"synthetic-receipt","Synthetic verified physical receipt",returned,f.operator.toString(),UUID.randomUUID()))).hasMessage("IDEMPOTENCY_HASH_MISMATCH");assertThat(f.jdbc.queryForObject("SELECT actor_kind FROM commerce.audit_record WHERE resource_id=? AND action='STOCK_TRANSITION' ORDER BY occurred_at DESC LIMIT 1",String.class,balance)).isEqualTo("USER");}
 @Test void fullyUnshippedCancellationReleasesAllocationWithoutClaimingDispatch(){UUID location=f.location(),sku=f.sku(0);f.adjust(sku,location,"2",0,"stock");UUID balance=f.balance(sku,location),order=f.orders.order(),line=f.line(order,sku,"2");f.tx.executeWithoutResult(t->f.ledger.reserve(order,Map.of(balance,"2"),Instant.now().plusSeconds(600),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));f.paid(order);f.tx.executeWithoutResult(t->f.ledger.allocate(order,UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));f.jdbc.update("UPDATE commerce.sales_order SET status='REFUNDING' WHERE id=?",order);f.tx.executeWithoutResult(t->f.ledger.returned(order,List.of(new StockLedger.Line(line,balance,"2")),StockLedger.ReturnKind.UNSHIPPED_CANCEL,"synthetic-cancel","Synthetic approved unshipped cancellation",UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.inventory_reservation WHERE order_id=?",String.class,order)).isEqualTo("RELEASED");assertThat(f.jdbc.queryForObject("SELECT on_hand::text||':'||allocated::text FROM commerce.inventory_balance WHERE id=?",String.class,balance)).isEqualTo("2.000:0.000");}
 @Test void lateSettlementCanRereserveOnlyAPrePaymentReleasedReservation(){UUID location=f.location(),sku=f.sku(0);f.adjust(sku,location,"2",0,"stock");UUID balance=f.balance(sku,location),order=f.orders.order();f.line(order,sku,"2");f.tx.executeWithoutResult(t->f.ledger.reserve(order,Map.of(balance,"2"),Instant.now().plusSeconds(600),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));f.jdbc.update("UPDATE commerce.sales_order SET status='CANCELLED' WHERE id=?",order);f.tx.executeWithoutResult(t->f.ledger.release(order,UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));f.jdbc.update("UPDATE commerce.sales_order SET status='PAYMENT_HOLD',hold_reason='STOCK_UNAVAILABLE' WHERE id=?",order);f.tx.executeWithoutResult(t->f.ledger.reserve(order,Map.of(balance,"2"),Instant.now().plusSeconds(600),UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));f.paid(order);f.tx.executeWithoutResult(t->f.ledger.allocate(order,UUID.randomUUID(),f.operator.toString(),UUID.randomUUID()));assertThat(f.jdbc.queryForObject("SELECT reserved::text||':'||allocated::text FROM commerce.inventory_balance WHERE id=?",String.class,balance)).isEqualTo("0.000:2.000");}
}
